import Item from "@marko-ui/shadcn/ui/item/item.marko";
import ItemMedia from "@marko-ui/shadcn/ui/item/media.marko";
import ItemContent from "@marko-ui/shadcn/ui/item/content.marko";
import ItemTitle from "@marko-ui/shadcn/ui/item/title.marko";
import ItemDescription from "@marko-ui/shadcn/ui/item/description.marko";
import ItemActions from "@marko-ui/shadcn/ui/item/actions.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";

<Item variant="outline" style="width: 400px;">
  <ItemMedia variant="icon">
    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M12 2v20M2 12h20"/></svg>
  </ItemMedia>
  <ItemContent>
    <ItemTitle>New feature available</ItemTitle>
    <ItemDescription>Check out the latest update to your dashboard.</ItemDescription>
  </ItemContent>
  <ItemActions>
    <Button type="button" variant="outline" size="sm">View</Button>
  </ItemActions>
</Item>

import Item from "@marko-ui/shadcn/ui/item/item.marko";
import ItemGroup from "@marko-ui/shadcn/ui/item/group.marko";
import ItemMedia from "@marko-ui/shadcn/ui/item/media.marko";
import ItemContent from "@marko-ui/shadcn/ui/item/content.marko";
import ItemTitle from "@marko-ui/shadcn/ui/item/title.marko";
import ItemDescription from "@marko-ui/shadcn/ui/item/description.marko";
import ItemActions from "@marko-ui/shadcn/ui/item/actions.marko";
import Avatar from "@marko-ui/shadcn/ui/avatar/avatar.marko";
import Button from "@marko-ui/shadcn/ui/button/button.marko";
import Icon from "@marko-ui/shadcn/ui/icon/icon.marko";

static const PEOPLE = [
  { username: "shadcn", avatar: "https://github.com/shadcn.png", email: "shadcn@vercel.com" },
  { username: "maxleiter", avatar: "https://github.com/maxleiter.png", email: "maxleiter@vercel.com" },
  { username: "evilrabbit", avatar: "https://github.com/evilrabbit.png", email: "evilrabbit@vercel.com" },
];

<ItemGroup class="max-w-sm">
  <for|person| of=PEOPLE by=(person) => person.username>
    <Item variant="outline">
      <ItemMedia>
        <Avatar src=person.avatar alt=person.username fallback=person.username.charAt(0).toUpperCase() class="grayscale"/>
      </ItemMedia>
      <ItemContent class="gap-1">
        <ItemTitle>${person.username}</ItemTitle>
        <ItemDescription>${person.email}</ItemDescription>
      </ItemContent>
      <ItemActions>
        <Button type="button" variant="ghost" size="icon" class="rounded-full" aria-label=`Invite ${person.username}`>
          <Icon name="Plus"/>
        </Button>
      </ItemActions>
    </Item>
  </for>
</ItemGroup>

import Item from "@marko-ui/shadcn/ui/item/item.marko";
import ItemGroup from "@marko-ui/shadcn/ui/item/group.marko";
import ItemHeader from "@marko-ui/shadcn/ui/item/header.marko";
import ItemContent from "@marko-ui/shadcn/ui/item/content.marko";
import ItemTitle from "@marko-ui/shadcn/ui/item/title.marko";
import ItemDescription from "@marko-ui/shadcn/ui/item/description.marko";

static const models = [
  {
    name: "v0-1.5-sm",
    description: "Everyday tasks and UI generation.",
    image: "https://images.unsplash.com/photo-1650804068570-7fb2e3dbf888?q=80&w=640&auto=format&fit=crop",
  },
  {
    name: "v0-1.5-lg",
    description: "Advanced thinking or reasoning.",
    image: "https://images.unsplash.com/photo-1610280777472-54133d004c8c?q=80&w=640&auto=format&fit=crop",
  },
  {
    name: "v0-2.0-mini",
    description: "Open Source model for everyone.",
    image: "https://images.unsplash.com/photo-1602146057681-08560aee8cde?q=80&w=640&auto=format&fit=crop",
  },
];

<div class="flex w-full max-w-xl flex-col gap-6">
  <ItemGroup class="grid grid-cols-3 gap-4">
    <for|model| of=models by=(model) => model.name>
      <Item variant="outline">
        <ItemHeader>
          <img src=model.image alt=model.name width="128" height="128" class="aspect-square w-full rounded-sm object-cover"/>
        </ItemHeader>
        <ItemContent>
          <ItemTitle>${model.name}</ItemTitle>
          <ItemDescription>${model.description}</ItemDescription>
        </ItemContent>
      </Item>
    </for>
  </ItemGroup>
</div>
